<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api} from './api'
import {locale, message, t} from './i18n'
const data=ref<Record<string,any>>(),err=ref(''),busy=ref(false)
const l=(a:string,b:string)=>locale.value==='ar'?b:a
const ar:Record<string,string>={connector_strength:'قوة مفتاح الموصل',connector_separate:'استقلال مفتاح الموصل',outbox:'الأحداث الصادرة',pending:'معلّق',failed:'فشل',keys:'مفاتيح التوقيع',separate:'فصل المفاتيح',staff_strength:'قوة مفتاح الموظفين التقديرية',portal_strength:'قوة مفتاح العملاء التقديرية',portal_key_configured:'مفتاح مستقل مضبوط',mfa:'التحقق متعدد العوامل',active_users:'مستخدمون نشطون',enrolled:'مسجلون',enforced:'ينطبق عليهم الإلزام',all:'إلزام الجميع',sessions:'الجلسات',staff:'جلسات الموظفين',external:'جلسات العملاء',staff_last:'آخر نشاط موظف',external_last:'آخر نشاط عميل',backup:'النسخ الاحتياطي',latest:'آخر نسخة محلية',pre_upgrade:'آخر نسخة قبل الترقية',recent:'نسخة خلال ٤٨ ساعة',retention:'عدد النسخ المحتفظ بها',runtime:'إعدادات التشغيل',debug:'وضع التطوير',hosts:'المضيفون المسموحون',csrf:'حماية الطلبات',secure_cookie:'ملف ارتباط آمن',https:'اتصال مشفر',frame_options:'سياسة تضمين الصفحة',portal_csp:'سياسة محتوى البوابة'}
const title=(k:string)=>l(k.replaceAll('_',' '),ar[k]||k)
async function load(){try{data.value=await api('/platform/v1/security/health')}catch(e){err.value=message(e)}}
function healthy(k:string,v:any){if(k==='outbox')return !v.failed;if(k==='keys')return Object.values(v).every(Boolean);if(k==='backup')return v.recent&&v.pre_upgrade;if(k==='runtime')return !v.debug&&v.csrf&&v.https&&v.secure_cookie;if(k==='mfa')return v.enrolled===v.active_users;return true}
async function revoke(kind:string){if(!confirm(t('Revoke all sessions in this group?')))return;busy.value=true;try{await api('/platform/v1/security/revoke-all','POST',{kind});if(kind==='staff')location.reload();else await load()}catch(e){err.value=message(e)}finally{busy.value=false}}
const explanations:Record<string,[string,string]>={"connector_strength": ["Estimated strength of the connector encryption key.", "تقدير قوة مفتاح تشفير الموصلات."], "connector_separate": ["Connector secrets need an independent encryption key.", "يتطلب تشفير أسرار الموصلات مفتاحًا مستقلاً."], "separate": ["Staff sessions and customer tokens must use different keys.", "يجب فصل مفاتيح جلسات الموظفين عن رموز العملاء."], "staff_strength": ["Estimated strength of the staff signing key.", "تقدير قوة مفتاح توقيع الموظفين."], "portal_strength": ["Estimated strength of the customer signing key.", "تقدير قوة مفتاح توقيع العملاء."], "portal_key_configured": ["Production requires an explicitly configured portal key.", "يتطلب الإنتاج ضبط مفتاح البوابة صراحة."], "active_users": ["Accounts included in the enrollment denominator.", "عدد الحسابات الداخلة في حساب نسبة التسجيل."], "enrolled": ["Active users with an enrolled authenticator.", "الحسابات النشطة المسجلة في تطبيق المصادقة."], "enforced": ["Users required by policy to complete MFA.", "المستخدمون الملزمون بإكمال التحقق المتعدد."], "all": ["Indicates whether policy requires MFA for every staff account.", "هل تلزم السياسة كل موظف بالتحقق المتعدد؟"], "staff": ["Unexpired authenticated staff sessions.", "جلسات الموظفين الموثقة والسارية."], "external": ["Unrevoked active customer sessions.", "جلسات العملاء النشطة والسارية."], "staff_last": ["Latest observed staff activity.", "آخر نشاط مرصود للموظفين."], "external_last": ["Latest observed customer activity.", "آخر نشاط مرصود للعملاء."], "pending": ["Events with outstanding deliveries.", "أحداث لم يكتمل تسليمها."], "failed": ["Inspect the dispatcher for failed or retrying deliveries.", "راجع الموزّع عند فشل التسليم أو تكرار المحاولات."], "latest": ["Timestamp of the newest backup archive found.", "وقت أحدث ملف نسخة احتياطية تم العثور عليه."], "pre_upgrade": ["Timestamp of the newest pre-upgrade archive.", "وقت أحدث نسخة تسبق الترقية."], "recent": ["A local archive was found within 48 hours.", "عُثر على نسخة محلية خلال آخر 48 ساعة."], "retention": ["Configured number of archives retained.", "عدد النسخ المضبوط للاحتفاظ بها."], "debug": ["Expected locally; disable in production.", "متوقع محليًا ويجب تعطيله في الإنتاج."], "https": ["HTTP is normal on local WSL; production requires HTTPS.", "HTTP طبيعي محليًا على WSL، والإنتاج يتطلب HTTPS."], "hosts": ["Hostnames the application accepts.", "أسماء المضيفين التي يقبلها التطبيق."], "csrf": ["CSRF middleware protects session-based requests.", "تحمي طبقة CSRF طلبات جلسات المستخدمين."], "secure_cookie": ["Enable secure cookies behind production HTTPS.", "فعّل ملفات الارتباط الآمنة في الإنتاج مع HTTPS."], "frame_options": ["Browser policy controlling page embedding.", "سياسة المتصفح لتضمين الصفحة."], "portal_csp": ["Content policy used by the customer portal.", "سياسة المحتوى المستخدمة في بوابة العملاء."]}
const explain=(k:string)=>explanations[k]?l(...explanations[k]):''
onMounted(load)
</script><template><section class="stack"><h1>{{t('Security Health')}}</h1><button @click="load">{{t('Refresh')}}</button><p role="alert">{{err}}</p><article v-for="(v,k) in data" class="panel"><h2>{{title(String(k))}} · {{healthy(String(k),v)?t('Healthy'):t('Warning')}}</h2><dl class="health-grid"><div v-for="(value,field) in v"><dt>{{title(String(field))}}</dt><dd>{{typeof value==='boolean'?(value?t('Yes'):t('No')):value??t('Unknown')}}</dd><small>{{explain(String(field))}}</small></div></dl><div v-if="k==='sessions'" class="actions"><button :disabled="busy" @click="revoke('staff')">{{t('Revoke all staff sessions')}}</button><button :disabled="busy" @click="revoke('external')">{{t('Revoke all customer sessions')}}</button></div></article></section></template>
